window.MONSTER_CHUNK_145 = [{"name":"Sphinx Stone Idol","cr":10,"xp":9600,"alignment":"N","size":"Huge","type":"construct","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":29,"ac_touch":9,"ac_flat_footed":28,"ac_mods":"+1 Dex, +20 natural, -2 size","hp":117,"hd":"14d10+40","hdvalue":14,"fort":4,"ref":5,"will":4,"defensive_abilities":["rejuvenation"],"dr":"10/ adamantine","immunities":["construct traits (+40 hp)","magic"],"speed":[{"type":"land","speed":30},{"type":"fly","speed":50,"maneuverability":"average"}],"melee":"bite +20 (4d6+8), 2 claws +20 (2d6+8)","space":"15 ft.","reach":"10 ft.","special_attacks":[{"type":"breath weapon","details":"30 ft cone, 12d6 acid; DC 17 Ref half, usable every 1d4 rounds"},{"type":"roar"}],"strength":27,"dexterity":12,"wisdom":11,"charisma":10,"baseatk":14,"cmb":24,"cmd":35,"cmd_special":"+4 vs. trip","sq":[{"type":"site bound"}],"environments":["any"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"This statue is constructed of smooth stone and has a leonine body with the head of a jackal. Two large stony dragon-like wings protrude from its back. Ruby red gemstones seem to function as eyes.","group":"Stone Idol","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Immunity to Magic","kind":"Ex","details":"A stone idol is immune to any spell or spell-like ability that allows spell resistance. In addition, certain spells and effects function differently against the creature, as noted below. A transmute rock to mud spell slows a stone idol (as the slow spell) for 2d6 rounds, with no saving throw, while transmute mud to rock heals all of its lost hit points. A stone to flesh spell doesn't actually change the stone idol's structure but negates its damage reduction and immunity to magic for 1 full round. A disintegrate spell deals +50% damage to a stone idol. A chaos hammer, holy smite, order's wrath, or unholy blight spell deals 1d4 points of damage per two caster levels to a stone idol if the creator's alignment matches one of the aforementioned spells."},{"type":"Rejuvenation","kind":"Su","details":"Unless a stone idol's main body is shattered into small fragments and scattered to the winds, the creature reforms itself at full strength in 1d4+2 days."},{"type":"Site Bound","kind":"Ex","details":"A stone idol cannot travel more than 200 ft. from a central point designated by its creator. Once this point is selected, it can never be changed. A stone idol taken outside the area ceases functioning until it is brought back into the area."},{"type":"Roar","kind":"Su","details":"A sphinx stone idol can roar up to three times per day as a standard action. Affected creatures become frightened for 2d6 rounds. A DC 17 Will save negates the effect. The roar is a mind-affecting fear effect and a sonic effect that fills a 100-foot-radius burst, centered on the stone idol sphinx. A creature that successfully saves cannot be affected again by the same sphinx stone idol's roar for one day. The save DC is Charisma-based."}],"description":"A stone idol sphinx is about 15 ft. long and weighs around 29,000 pounds. A sphinx stone idol often has the head of an animal considered sacred by the religion: jackal-headed, goat-headed, vulture-headed, and so on.\n\nA stone idol sphinx attacks first using its roar and then using its vicious bite and slashing with its stony paws. It often takes to the air where it can gain an advantage on its foes.\n\nConstruction\n\nA stone idol sphinx is chiseled from a block of smooth stone that weighs at least 6,000 pounds. It must be of exceptional quality and have a value of not less than 10,000 gp.\n\nSPHINX STONE IDOL\n\nCL 14th; Price 110,000 gp\n\nRequirements Craft Construct, acid fog, fear, shout, creator must be caster level 14th; Skill Craft (sculpting) or Craft (stonemasonry) DC 19; Cost 65,000 gp.","ecology":"","habitat_society":""},{"name":"Spider Lich","cr":10,"xp":9600,"alignment":"CE","size":"Large","type":"undead","init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"auras":["fear (60 ft. radius, DC 19)"],"ac":19,"ac_touch":12,"ac_flat_footed":16,"ac_mods":"+3 Dex, +7 natural, -1 size","hp":102,"hd":"12d8+48","hdvalue":12,"fort":7,"ref":7,"will":10,"defensive_abilities":["channel resistance +4"],"dr":"15/bludgeoning and magic","immunities":["cold","electricity","undead traits"],"speed":[{"type":"land","speed":40},{"type":"climb","speed":40}],"melee":"bite +11 (2d8+3 plus paralysis and poison)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"web","details":"+11 ranged, DC 19, 12 hp"}],"spellsknown_caster_level":12,"spellsknown_concentration":16,"spellsknown":[{"spell_level":6,"spell_slots":3,"spells":[{"spell":"chain lightning"}]},{"spell_level":5,"spell_slots":5,"spells":[{"spell":"cloudkill"},{"spell":"dominate person"}]},{"spell_level":4,"spell_slots":6,"spells":[{"spell":"bestow curse"},{"spell":"crushing despair"},{"spell":"enervation"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"fireball"},{"spell":"haste"},{"spell":"rage"},{"spell":"slow"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"alter self"},{"spell":"blur"},{"spell":"darkness"},{"spell":"see invisibility"},{"spell":"web"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"burning hands"},{"spell":"jump"},{"spell":"ray of enfeeblement"},{"spell":"shield"},{"spell":"true strike"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"bleed"},{"spell":"daze"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"light"},{"spell":"mage hand"},{"spell":"ray of frost"},{"spell":"touch of fatigue"}]}],"strength":15,"dexterity":17,"intelligence":16,"wisdom":14,"charisma":16,"baseatk":9,"cmb":12,"cmd":28,"cmd_special":"+8 vs. trip","feats":[{"feat":"Blind-Fight"},{"feat":"Combat Casting"},{"feat":"Defensive Combat Training"},{"feat":"Empower Spell"},{"feat":"Toughness"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Acrobatics","value":11},{"skill":"Climb","value":25},{"skill":"Intimidate","value":18},{"skill":"Knowledge (arcana)","value":18},{"skill":"Knowledge (planes)","value":9},{"skill":"Perception","value":21},{"skill":"Sense Motive","value":11},{"skill":"Spellcraft","value":18},{"skill":"Stealth","value":18}],"languages":["Common","Undercommon","plus two others"],"sq":[{"type":"rejuvenation"}],"environments":["any"],"organizations":["solitary","troop (1 spider lich plus 2-4 wraiths or spectres)"],"treasure":"standard","description_visual":"This chill of death emanates from this giant skeletal spider. Its blackened eyes show a remarkable intelligence.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Fear Aura","kind":"Su","details":"Creatures of less than 5 HD in a 60-foot radius that look at the spider lich must succeed on a DC 19 Will save or become frightened. Creatures with 5 HD or more must succeed at a Will save or be shaken for 1d6+6 rounds. A creature that successfully saves cannot be affected again by the same spider lich's aura for one day. This is a mind-affecting fear effect."},{"type":"Paralyzing Bite","kind":"Su","details":"Any living creature a spider lich hits with its bite attack must succeed on a DC 19 Fortitude save or be paralyzed for 1d6+12 minutes. Remove paralysis or any spell that can remove a curse can free the victim (see the bestow curse spell description). The effect cannot be dispelled. Anyone paralyzed by a spider lich seems dead, though a DC 20 Perception check or a DC 15 Heal check reveals that the victim is still alive."},{"type":"Poison","kind":"Ex","details":"Bite-injury; save DC 21 Fort; frequency 1/round for 6/rounds; effect 1d4 Strength damage; cure 1 save. The save is Charisma-based and includes a +2 racial bonus."},{"type":"Rejuvenation","kind":"Su","details":"When a spider lich is destroyed, its phylactery (which is generally hidden by the spider lich in a safe place far from where it chooses to dwell) immediately begins to rebuild the undead spider lich's body nearby. This process takes 1d10 days-if the body is destroyed before that time passes, the phylactery merely starts the process anew. Spells A spider lich doesn't require any verbal, somatic, or material components to cast its spells."}],"description":"The true origin of the spider lich is shrouded in mystery. Scholars argue constantly about its origins and how it came into existence. Some stand by the theory that intelligent giant spiders, perhaps phase spiders or some offshoot race of that dreaded creature, discovered the path to lichdom. Others contend a spider lich is the byproduct of a failed sorcerer's attempt at lichdom. Still others argue that the spider lich is simply a spellcaster's chosen form once it achieved lichhood. Whatever its true origins, the spider lich is truly a dreaded creature that many adventurers hope they never run across.\n\nSpider liches are most often encountered underground in dungeons, caves, and crypts or in ruined temples and shrines, leading to further speculation among scholars as to the creature's origins. They don't associate with true spiders but are often encountered with other undead, particularly wraiths and spectres.\n\nSpider liches have an insatiable thirst for knowledge. Countless days, months, years are spent pouring over ancient texts and tomes. Though evil by nature, spider liches often work with other creatures, particularly evil spellcasters to quench their thirst for this knowledge.\n\nSpider liches stand over 8 ft. tall and resemble skeletal spiders. Their eight eyes are deep black in color. Other than the sound of their bony legs clattering across stone floors, these creatures make no sound. They can speak a variety of languages but rarely do so.\n\nThe Spider Lich's Phylactery\n\nAn integral part of becoming a spider lich is the creation of the phylactery in which the creature stores its spirit. The only way to get rid of a spider lich for sure is to destroy its phylactery. Unless its phylactery is located and destroyed, a spider lich can rejuvenate after it is killed.\n\nThe typical spider lich phylactery is a gemstone of not less than 1,000 gp value. The spider lich hides the gemstone in a safe place and wraps it securely in a complex mesh of super strong webbing (DR 10/-, 24 hp).","ecology":"","habitat_society":""},{"name":"Splinter Drake","cr":10,"xp":9600,"alignment":"NE","size":"Large","type":"plant","init":2,"senses":[{"type":"low-light vision"}],"ac":23,"ac_touch":11,"ac_flat_footed":21,"ac_mods":"+2 Dex, +12 natural, -1 size","hp":178,"hd":"17d8+102","hdvalue":17,"fort":16,"ref":7,"will":8,"immunities":["plant traits"],"resists":[{"type":"fire","value":10}],"speed":[{"type":"land","speed":40}],"melee":"bite +20 (2d6+8/19-20), 2 claws +19 (1d6+8)","ranged":"thorn volley +13 (3d6)","space":"10 ft.","reach":"5 ft. (10 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"40 ft. cone, DC 24, 6d6 slashing and piercing"},{"type":"poison"}],"strength":27,"dexterity":15,"constitution":23,"intelligence":10,"wisdom":12,"charisma":10,"baseatk":12,"cmb":21,"cmd":33,"cmd_special":"+4 vs. trip","feats":[{"feat":"Cleave"},{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Great Cleave"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Natural Attack (bite)"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Perception","value":21},{"skill":"Stealth","value":17,"special":"+29 in forested areas"}],"languages":["Common","Sylvan"],"sq":[{"type":"improved woodland stride"}],"environments":["temperate forests"],"organizations":["solitary","pair"],"treasure":"half standard","description_visual":"This creature looks like a wingless dragon about 12 ft. long whose flesh is actually dark brown bark with a greenish hue. A bushy mane of twigs, branches, leaves, and vines circles its dragon-like head and a series of thorny spines runs the length of its back. Two backward curved horns, apparently constructed of the same hardened bark as its body, jut from the creature's head. A dark brown snake-like tongue flicks across its fangs as it advances.","group":"Drake","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Breath Weapon","kind":"Ex","details":"A splinter drake has two breath weapons, both of which emit razor-sharp thorns. The main breath weapon, useable every 1d4 rounds, is a 40-ft. cone that deals 6d6 points of piercing and slashing damage. Its other breath weapon is a volley of thorns spit at a single target as a ranged attack for 3d6 points of piercing damage."},{"type":"Improved Woodland Stride","kind":"Su","details":"A splinter drake can move through any sort of undergrowth (natural thorns, briars, overgrown areas, and similar terrain) at its normal speed without taking damage or suffering other impairment. This includes thorns, briars, and overgrown areas that are magically manipulated to impede motion."},{"type":"Poison","kind":"Ex","details":"Three times per day as a free action, a splinter drake can regurgitate its poisonous stomach acids into its mouth and either use it in conjunction with a bite attack or release it along with either version of its breath weapon. The act of regurgitating the poison is a free action. Once it makes a successful bite attack or uses its breath weapon, the poison is used up (though the splinter drake can \"reload\" again on its next turn if it has any more uses of its poison attack left for the day). Splinter Drake Venom: Bite or breath weapon-injury or contact; save Fort DC 24; frequency 1/round for 5 rounds; effect 1d4 Con; cure 1 save."}],"description":"Splinter drakes are plant creatures that resemble large wingless dragons. They haunt dense forests and make their lairs amid the tangled underbrush, generally in hard-to-locate places. Much like true dragons, splinter drakes are extremely territorial and attack creatures that wander carelessly into their domain and remain for an extended amount of time. A typical splinter drake's territory covers an area of several square miles around its lair. Unlike true dragons, splinter drakes don't value nor keep treasure. Any treasure found in or around their lairs are likely all that remains of a past meal. They generally keep company with evil fey, evil druids, and corrupt rangers. Such allies are allowed a bit of leeway when treading on a splinter drake's territory, but if certain boundaries are crossed or privileges abused, splinter drakes have no problems eating someone they once called friend. Splinter drakes generally don't associate with others of their kind, except during mating season (early spring) when a mated pair is likely to be encountered. During mating, the female splinter drake deposits a host of eggs (or seeds) into the ground. Within several months, 1d4 new splinter drakes grow from the ground. Splinter drakes reach maturity within 1 year. A splinter drake is about 12 ft. long and weighs around 800 pounds. Splinter drakes typically ambush potential prey whenever possible, striking from surprise with their thorny breath weapon and poison. Once it releases its first blast, it charges into battle and slashes and tears at its foes with its claws and bite. If outnumbered or combat turns against it, a splinter drake seeks the quickest means of exit possible unless cornered, defending its lair, or starving, in which case it fights to the death. Rarely, though not completely unheard of, a splinter drake takes levels in a class, almost always the druid or ranger class.","ecology":"","habitat_society":""},{"name":"Stirge Demon","cr":10,"xp":9600,"alignment":"CE","size":"Large","type":"outsider","subtypes":["chaotic","demon","evil","extraplanar"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["drone (60 ft., DC 20). fear (20 ft., DC 16)"],"ac":23,"ac_touch":12,"ac_flat_footed":20,"ac_mods":"+3 Dex, +11 natural, -1 size","hp":92,"hd":"8d10+48","hdvalue":8,"fort":12,"ref":9,"will":6,"dr":"10/good","immunities":["electricity and poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10},{"type":"fire","value":10}],"sr":21,"speed":[{"type":"land","speed":20},{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"2 claws +13 (2d4+6 plus 1d4 bleed), bite +13 (2d6+6  plus blood drain)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"blood drain","details":"1d4 Constitution"},{"type":"drone"},{"type":"wounding"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":16,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"darkness"},{"spell":"dispel magic"},{"spell":"greater teleport","details":"self plus 50 pounds of objects only"},{"spell":"see invisibility"},{"spell":"telekinesis"}]},{"frequency":"1/day","spells":[{"spell":"summon","details":"level 4, 2d8 dretches or 1 stirge demon 35%"}]}],"strength":22,"dexterity":17,"constitution":23,"intelligence":14,"wisdom":14,"charisma":15,"baseatk":8,"cmb":15,"cmd":28,"cmd_special":"+4 vs. trip","feats":[{"feat":"Blind-Fight"},{"feat":"Cleave"},{"feat":"Power Attack"},{"feat":"Iron Will"}],"skills":[{"skill":"Bluff","value":10},{"skill":"Climb","value":18},{"skill":"Escape Artist","value":11},{"skill":"Fly","value":16},{"skill":"Intimidate","value":13},{"skill":"Knowledge (planes)","value":10},{"skill":"Perception","value":21},{"skill":"Sense Motive","value":13},{"skill":"Stealth","value":10},{"skill":"Survival","value":13}],"languages":["Abyssal","Common","Undercommon","telepathy 100 ft."],"environments":["any (Abyss)"],"organizations":["solitary","gang (2-4)","squad (5-6)"],"treasure":"standard","description_visual":"The creature is a loathsome cross between a human, a stirge, and an abyssal fly. It stands on four stirge-like hind legs and grasps with its humanlike forelimbs, which end in chitinous claw-like fingers. It has the wings of a stirge, though wrinkled and seemingly useless. Its stirge-like head has distinctly human features and is topped with a bristled, backswept mane. Its mouth is tiny and filled with fangs, though its nose is long and sharp and is used to pierce and draw blood.","group":"Demon","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Drone","kind":"Su","details":"At all times, save when using any spell-like abilities, the stirge demon drones and buzzes like a fly. All creatures within a 60-foot spread that hear it must succeed on a DC 20 Will save or fall into a comatose sleep for 1d4 hours. There is no HD limit for this effect and it otherwise functions as the sleep spell (CL 10th). Note, the stirge demon can drain blood from a sleeping creature without automatically waking it up. In such an event, the sleeping creature receives a new Will save (same DC) each round the stirge demon drains blood. The save DCs are Constitution-based."}],"description":"One of the most foul and despicable of all demonkind, the stirge demon hates all other demonic races and usually attacks them on sight. It savors the blood of vrocks and hezrous, but generally avoids any more powerful demonic races. Stirge demons play no role in the Abyssal armies as most demon lords and princes find them hard to control and consider them pests to be exterminated. Other demons loathe them as well, and usually attack them when they are encountered.\n\nA stirge demon is about 10 ft. long and weighs 800 pounds.\n\nStirge demons enter combat and attempt to drone as many of their opponents to sleep as they can. Creatures that resist are attacked with claws and bite. Once the stirge demon has droned all its opponents to sleep, or they have fled, it feasts on any sleeping creatures, draining their blood. If outnumbered or overmatched, a stirge demon doesn't engage an enemy. If confronted by foes more powerful than it, the stirge demon uses its greater teleport to escape.","ecology":"","habitat_society":"","credit":"The Stirge demon is loosely based on the Chasme Demon, which originally appeared in the First Edition module S4 Lost Caverns of Tsojcanth (© TSR/Wizards of the Coast, 1982) and later in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission. The stirge demon made its d20 debut in the Necromancer Games module D1 Tomb of Abysthor (©2001, Clark Peterson, Necromancer Games, Inc.)."},{"name":"Sword Spider","cr":10,"xp":9600,"alignment":"N","size":"Large","type":"construct","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":25,"ac_touch":10,"ac_flat_footed":24,"ac_mods":"+1 Dex, +15 natural, -1 size","hp":112,"hd":"15d10+30","hdvalue":15,"fort":5,"ref":6,"will":5,"dr":"10/adamantine","immunities":["construct traits (+30 hp)","magic"],"speed":[{"type":"land","speed":20},{"type":"climb","speed":20}],"melee":"sword-leg +16 (2d6+2/19-20), 3 sword-legs +16 (2d6+2/19-20), bite +16 (1d8+2 plus poison)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"sword-legs"}],"strength":14,"dexterity":12,"wisdom":11,"charisma":1,"baseatk":15,"cmb":18,"cmd":29,"cmd_special":"+12 vs. trip","skills":[{"skill":"Climb","value":10}],"environments":["any"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"This enormous spider is constructed from steel and its eight legs end in large sharpened blades.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Immunity to Magic","kind":"Ex","details":"A sword spider is immune to any spell or spell-like ability that allows spell resistance, except as noted: A keen edge spell affects all of a sword spider's sword-leg attacks as if they were slashing weapons. Transmute metal to wood slows a sword spider for 1d4 rounds (as the slow spell), during which time its damage reduction is negated (no save). A magical attack that deals fire damage ends any slow effect on the sword spider and heals 1 point of damage for each 3 points of damage the attack would otherwise deal. If the amount of healing would cause the sword spider to exceed its full normal hit points, it gains any excess as temporary hit points. A sword spider gets no saving throw against fire effects. A sword spider is affected normally by rusting attacks, such as those of a rust monster or a rusting grasp spell."},{"type":"Poison","kind":"Ex","details":"A sword spider's bite injects poison from a hidden reservoir within its metal body. Because it is a construct, the sword spider doesn't naturally produce this poison, and its creator must manually refill this reservoir. The reservoir holds enough poison for 5 successful bite attacks, after which the sword spider deals only bite damage. Refilling the reservoir takes 1 minute and provokes attacks of opportunity. The creator can fill the reservoir with any injury poison (typically spider venom), though acid, alchemical substances, and even stranger liquids have been used. Giant Spider Venom: Bite-injury; save DC 14 Fort; frequency 1/round for 4 rounds; effect 1d2 Strength damage; cure 1 save."},{"type":"Sword-Legs","kind":"Ex","details":"A sword spider's legs act as longswords, granting it iterative attacks just as if it wielded multiple weapons. It cannot be disarmed and a sword spider never takes penalties to its attack rolls (for multiweapon fighting) when fighting with its sword-legs."}],"description":"A sword spider resembles a giant-sized arachnid constructed of steel. Its eight spidery legs end in large sharpened blades resembles longswords or greatswords. A typical sword spider stands 10 ft. tall and weighs 3,000 pounds.\n\nWhen activated, a sword spider fights relentlessly and tirelessly to vanquish its foes, slashing them with up to four of its sword-like legs.\n\nConstruction\n\nA sword spider's body is constructed from at least 3,000 pounds of smelted steel. The metal must be of exceptional quality, and costs at least 5,000 gp.\n\nSWORD SPIDER\n\nCL 14th; Price 122,000 gp\n\nRequirements Craft Construct, antimagic field, geas/quest, keen edge, poison, creator must be caster level 14th; Skill Craft (sculpting) or Craft (metalworking) DC 19; Cost 63,500 gp","ecology":"","habitat_society":""},{"name":"Tentacled Horror","cr":10,"xp":9600,"alignment":"CE","size":"Huge","type":"aberration","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"30 ft."}],"auras":["insanity (sight, DC 23)"],"ac":22,"ac_touch":8,"ac_flat_footed":22,"ac_mods":"+14 natural, -2 size","hp":142,"hd":"15d8+75","hdvalue":15,"hp_mods":["regeneration 5 (cold or fire)"],"fort":10,"ref":7,"will":7,"defensive_abilities":["horn"],"resists":[{"type":"acid","value":10}],"sr":21,"speed":[{"type":"land","speed":30}],"melee":"4 tentacles +16 (1d8+7/19-20 plus grab), bite +16  (3d6+7)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"constrict","details":"1d8+7"}],"strength":24,"dexterity":10,"constitution":21,"intelligence":14,"wisdom":16,"charisma":18,"baseatk":11,"cmb":6,"cmb_special":"+4 vs. grapple","cmd":17,"cmd_special":"can't be tripped","feats":[{"feat":"Ability Focus (aura of insanity)"},{"feat":"Blind-Fight"},{"feat":"Cleave"},{"feat":"Critical Focus"},{"feat":"Improved Critical (tentacle)"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"}],"skills":[{"skill":"Bluff","value":19},{"skill":"Intimidate","value":22},{"skill":"Knowledge (arcana)","value":20},{"skill":"Knowledge (dungeoneering)","value":17},{"skill":"Perception","value":21},{"skill":"Sense Motive","value":18}],"languages":["Aklo","Goblin","Undercommon"],"environments":["any underground"],"organizations":["solitary"],"treasure":"standard","description_visual":"Four tentacles emerge from the torso of this massive misshapen creature. Above these are a tooth-encrusted maw and a glaring red eye.  At the top of the creature is a glistening black horn.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Aura of Insanity","kind":"Su","details":"Creatures with less than 6 HD that view a tentacled horror must make a DC 23 Will save or be affected as if by an insanity spell (caster level 12th). Creatures of 2 HD or less are not only driven mad but are also compelled to worship the tentacled horror as a god (as if affected by a charm person spell, caster level 12th). Only a restoration, greater restoration, miracle, or wish spell can restore the mind of one driven insane by a tentacled horror. The save DC is Charisma-based and includes +2 for its Ability Focus feat."},{"type":"Horn","kind":"Su","details":"The source of a tentacled horror's power is its horn. If a tentacled horror's horn is removed, it loses its regeneration ability and suffers a -6 penalty to Strength and Constitution until the horn is reattached. The horn is AC 20, hardness 10, and has 20 hit points. A tentacled horror's horn cannot be removed unless it is helpless. It takes a successful DC 40 Strength or 10 points of damage to the horn to remove a tentacled horror's horn."}],"description":"Ancient and evil, a tentacled horror is a monstrosity from the unknown depths of the earth. This monster is most often found inhabiting dungeons or ruins far from the reaches of civilization.\n\nTentacled horrors are egotistical and lazy creatures, and put themselves above all others they encounter. Often, a tentacled horror that finds its way into a subterranean society will attempt to set itself up as a god.\n\nLesser creatures such as goblins often accept this false god and bring it sacrifices of living victims. Once ensconced as ruler-deity, a tentacled horror is content to remain in one place to be cared for by its subjects. A tentacled horror that has been in power for some time will be surrounded by a pool of its own slime and the scattered bones of its victims.\n\nExuding a foul oily slime wherever it goes, a tentacled horror has a powerful humanoid torso that ends in a thick slug-like foot. Sprouting from the torso are four whip-like tentacles tipped in cruel barbs. Most horrifying of all, however, is the face. A tentacled horror has a shapeless head with a single, huge, unblinking eye. The mouth of a tentacled horror is a yawning chasm of sharp teeth eager to sink into living flesh. Above the eye is a glistening black 2-foot long horn-the very source of the tentacled horror's power.\n\nA tentacled horror attacks first with its tentacles, ripping and tearing at its opponent with the sharp barbs at the tip. Any grappled opponent is immediately bitten.","ecology":"","habitat_society":""},{"name":"Tarry Demodand","cr":10,"xp":9600,"alignment":"CE","size":"Medium","type":"outsider","subtypes":["chaotic","demodand","evil","extraplanar"],"init":5,"senses":[{"type":"darkvision","modifier":"120 ft."}],"ac":27,"ac_touch":15,"ac_flat_footed":22,"ac_mods":"+5 Dex, +12 natural","hp":104,"hd":"11d10+44","hdvalue":11,"fort":11,"ref":8,"will":5,"dr":"10/good and magic","immunities":["acid","poison","mindaffecting effects"],"resists":[{"type":"cold","value":10},{"type":"fire","value":10}],"sr":21,"speed":[{"type":"land","speed":40},{"type":"fly","speed":60,"maneuverability":"average"}],"melee":"2 claws +19 (1d6+7 plus grab), bite +18 (1d8+7)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"adhesive"},{"type":"rage"}],"spell_like_abilities_caster_level":11,"spell_like_abilities_concentration":15,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect good"},{"spell":"detect magic"},{"spell":"detect thoughts"},{"spell":"fear"},{"spell":"gaseous form"},{"spell":"invisibility","details":"self only"},{"spell":"magic circle against good"},{"spell":"see invisibility"},{"spell":"tongues"}]},{"frequency":"1/day","spells":[{"spell":"chaos hammer"},{"spell":"summon","details":"level 4, 1d2 tarry demodands 40%"}]},{"frequency":"3/day","spells":[{"spell":"dispel magic"},{"spell":"fog cloud"},{"spell":"ray of enfeeblement"}]}],"strength":24,"dexterity":20,"constitution":19,"intelligence":12,"wisdom":12,"charisma":16,"baseatk":11,"cmb":2,"cmd":15,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Cleave"},{"feat":"Great Cleave"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Weapon Focus (claws)"}],"skills":[{"skill":"Bluff","value":17},{"skill":"Fly","value":13},{"skill":"Knowledge (arcana)","value":15},{"skill":"Knowledge (planes)","value":15},{"skill":"Perception","value":19},{"skill":"Sense Motive","value":12},{"skill":"Stealth","value":19},{"skill":"Survival","value":15}],"languages":["Abyssal","Common"],"environments":["any (Tarterus)"],"organizations":["solitary","troupe (2-5)"],"treasure":"standard","description_visual":"This creature appears as a tall, powerful gray-skinned humanoid with green eyes and a long, oval, amphibious head. Two large, dull gray batlike wings sprout from its shoulders. Its hands end in blackened claws.","group":"Demodand","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Adhesive","kind":"Ex","details":"A tarry demodand exudes a thick tar-like substance that acts as a powerful adhesive, holding fast any creatures or items touching it. A tarry demodand has a +4 racial bonus on grapple checks due to its tarry secretions in addition to that provided by its grab ability. A weapon that strikes a tarry demodand is stuck fast unless the wielder succeeds on a DC 19 Reflex save. A successful DC 19 Strength check is needed to pry it off. The save DC and check DC are Constitution-based. Strong alcohol dissolves the adhesive. A pint of wine or a similar liquid weakens it, but the tarry demodand can still grapple normally. A tarry demodand can dissolve its adhesive at will, and the substance breaks down 1 minute after the creature dies."},{"type":"Rage","kind":"Ex","details":"A tarry demodand that takes damage in combat has a 50% chance of flying into a berserk rage the following round, clawing and biting madly until either it or its opponent is dead. It gains +4 Strength and -4 AC. The creature cannot end its rage voluntarily. While raging, make the following adjustments to the tarry demodand's statistics: AC 23, touch 11, flat-footed 18; CMB +20 (+28 grapple); CMD 35; Melee 2 claws +21 melee (1d6+9), bite +20 melee (1d8+9); Str 28."}],"description":"The cruel and malevolent tarry demodands wander the planes of Tarterus as soldiers and warriors in the mighty demodand armies. They are often employed by the shaggy demodands to battle daemons, demons, and devils. Tarry demodands care little for anything and attack just about anything weaker than them. A typical tarry demodand stands 7 ft. tall and weighs about 420 pounds. The tarry demodand attacks with its claws and bite, though it usually opens combat using its spell-like abilities. Should it fly into a rage, it attacks relentlessly until its opponent is slain. Any creature that becomes stuck to the tarry demodand is shredded by its wicked claws.","ecology":"","habitat_society":"","credit":"The Tarry Demodand originally appeared in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Woodwose","cr":10,"xp":9600,"alignment":"NE","size":"Medium","type":"fey","init":7,"senses":[{"type":"low-light vision"},{"type":"plant sense","modifier":"60 ft."}],"ac":24,"ac_touch":14,"ac_flat_footed":20,"ac_mods":"+3 Dex, +1 dodge, +10 natural","hp":127,"hd":"17d6+68","hdvalue":17,"fort":9,"ref":13,"will":13,"defensive_abilities":["plant passivism"],"dr":"10/cold iron","immunities":["wood"],"speed":[{"type":"land","speed":30}],"melee":"club +11 (1d6+3) or 2 slams +11 (1d6+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"spines"}],"spell_like_abilities_caster_level":17,"spell_like_abilities_concentration":25,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"ironwood"},{"spell":"tree shape"}]},{"frequency":"3/day","spells":[{"spell":"blight"},{"spell":"transport via plants"},{"spell":"wall of thorns"}]}],"spellsprepared_caster":"druid","spellsprepared_caster_level":9,"spellsprepared_concentration":17,"spellsprepared":[{"spell_level":5,"spell_slots":1,"spells":[{"spell":"insect plague"}]},{"spell_level":4,"spell_slots":1,"spells":[{"spell":"giant vermin"},{"spell":"rusting grasp"}]},{"spell_level":3,"spell_slots":1,"spells":[{"spell":"contagion"},{"spell":"dominate animal"},{"spell":"snare"}]},{"spell_level":2,"spell_slots":1,"spells":[{"spell":"barkskin"},{"spell":"chill metal"},{"spell":"fire trap"},{"spell":"flaming sphere"},{"spell":"heat metal"}]},{"spell_level":1,"spell_slots":1,"spells":[{"spell":"detect animals and plants"},{"spell":"endure elements"},{"spell":"faerie fire"},{"spell":"magic stone"},{"spell":"summon nature's ally I"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"flare"},{"spell":"guidance"},{"spell":"know direction"},{"spell":"read magic"},{"spell":"resistance"}]}],"strength":17,"dexterity":16,"constitution":18,"intelligence":13,"wisdom":16,"charisma":18,"baseatk":8,"cmb":11,"cmd":25,"feats":[{"feat":"Alertness"},{"feat":"Blind-Fight"},{"feat":"Combat Casting"},{"feat":"Dodge"},{"feat":"Empower Spell"},{"feat":"Improved Initiative"},{"feat":"Quicken Spell"},{"feat":"Stealthy"}],"skills":[{"skill":"Bluff","value":22},{"skill":"Craft (alchemy)","value":21},{"skill":"Craft (any)","value":21},{"skill":"Diplomacy","value":17},{"skill":"Knowledge (nature)","value":21},{"skill":"Perception","value":27},{"skill":"Sense Motive","value":27},{"skill":"Stealth","value":17,"special":"+21 in forests"}],"languages":["Common","Sylvan"],"environments":["temperate forests"],"organizations":["solitary"],"treasure":"standard (club)","description_visual":"This green skinned green haired figure has the appearance of a gnarled old man with skin like tree bark. Its hair and beard looks like Spanish moss with brambles and leaves knotted through it.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Immunity to Wood","kind":"Ex","details":"A woodwose is unaffected by wooden weapons (such as clubs or quarterstaffs) and spells or effects that generate or use wood-type effects (such as a wall of thorns for example). Weapons with damaging parts that are primarily metal (or some other material) such as arrows, spears, and so on, damage a woodwose normally."},{"type":"Plant Passivism","kind":"Ex","details":"No plant creatures willingly attack a woodwose. They can be forced to do so through magical means however. If attacked by a woodwose or one of its allies, the effect is broken and the plant creature can attack the woodwose normally."},{"type":"Plantsense","kind":"Ex","details":"A woodwose can automatically sense the location of anything within 60 ft. that is in contact with vegetation. Spells A woodwose casts spells as a 9th-level druid."},{"type":"Spines","kind":"Ex","details":"As a free action, a woodwose can cause sharpened wooden spines to protrude from its body. Any creature in contact with the woodwose or grappling with it takes 1d6 points of piercing damage each round it remains in contact with the woodwose. In addition, any creature attacking a woodwose with natural weapons or unarmed attacks takes the same 1d6 points of damage."}],"description":"The woodwose or green men are wicked male counterparts of the dryad.\n\nGuardians and protectors of forests and woodlands, woodwose have a cruel streak, feeling it better to bury an intruder amongst the trees than ever let them leave their forested sanctuaries again. Due to their malign nature, woodwoses don't associate with dryads, most sprites, or other benign woodland creatures. They do however sometimes form bonds and alliances with other evil fey creatures (such as redcaps and quicklings).\n\nWoodwoses have great magical powers like those of a druid, whom they seek to thwart and destroy when given the opportunity.\n\nA woodwose stands 5 ft. tall and weighs about 150 pounds. Its skin is dark brown and rough and course to the touch. Its hair is dark greenishbrown.\n\nA woodwose's eyes are deep chestnut brown.\n\nWoodwoses primarily fight using spells and spell-like abilities. In melee combat they lash out with powerful slam attacks or use thick wooden clubs and cause great spines to sprout from their body after the manner of a porcupine.","ecology":"","habitat_society":""},{"name":"Woolly Rhinoceros","cr":10,"xp":9600,"alignment":"N","size":"Large","type":"animal","init":0,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":19,"ac_touch":9,"ac_flat_footed":19,"ac_mods":"+10 natural, -1 size","hp":138,"hd":"12d8+84","hdvalue":12,"fort":16,"ref":8,"will":5,"speed":[{"type":"land","speed":30}],"melee":"gore +19 (2d6+15/19-20)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"powerful charge","details":"gore, 8d6+24"},{"type":"trample","details":"1d6+15, DC 26"}],"strength":31,"dexterity":10,"constitution":23,"intelligence":2,"wisdom":13,"charisma":2,"baseatk":9,"cmb":20,"cmd":30,"cmd_special":"+4 vs. trip","feats":[{"feat":"Endurance"},{"feat":"Great Fortitude"},{"feat":"Improved Critical (gore)"},{"feat":"Skill Focus (Perception)"},{"feat":"Toughness"},{"feat":"Weapon Focus (gore)"}],"skills":[{"skill":"Perception","value":22}],"environments":["cold forests","any marshes","any plains","temperate forests"],"organizations":["solitary","herd (2-8)"],"treasure":"none","description_visual":"This creature has massive legs and a stout body with a thick coat of brown fur. From the tip of its elongated nose rise two curving horns.","group":"Rhinoceros","source":"Tome of Horrors Complete (3pp)","description":"The woolly rhino is a herbivore of the Pleistocene era feeding mainly on various plants, nuts, berries, and bark, as well as large quantities of water.\n\nThus, it is usually found in areas plentiful with water, such as riverbanks, lakes, and even marshes and swamps. The woolly rhino usually forages in the morning so encounters are more common at this time. It is mostly a solitary creature though chance encounters at a common foraging area may lead to encounters with more than one creature. Herds tend to gather near watering grounds with the females surrounding the young.\n\nWoolly rhinos mate during the late summer or early fall. Gestation lasts about 450 days after which time the female gives birth to a single calf.\n\nCalves are dependent on their mother for about the first two years of their life. Around three years of age, the calf becomes completely independent and reaches maturity by age five.\n\nThe woolly rhino averages about 11 ft. long and has two ivory horns, the longest averaging about three ft. in length. Its body is covered in a thick layer of black, brown, ruddy, or yellowish-brown fur that enable it to withstand its harsh climate. The creature has poor eyesight, and relies on its senses of hearing and smell to locate sources of food and warn of impending danger.\n\nThe woolly rhino is generally passive, but reacts violently if it or its herd is threatened. It attacks by goring and trampling its foes, often opening combat by charging its foe.","ecology":"","habitat_society":""},{"name":"Adult Cloud Dragon","cr":11,"xp":12800,"alignment":"N","size":"Huge","type":"dragon","subtypes":["air"],"init":5,"senses":[{"type":"cloud vision"},{"type":"dragon senses"}],"auras":["frightful presence (180 ft., DC 21)"],"ac":28,"ac_touch":9,"ac_flat_footed":27,"ac_mods":"+1 Dex, +19 natural, -2 size","hp":161,"hd":"14d12+70","hdvalue":14,"fort":14,"ref":10,"will":15,"dr":"5/magic","immunities":["electricity","paralysis","sleep","winds"],"sr":18,"speed":[{"type":"land","speed":40},{"type":"fly","speed":200,"maneuverability":"poor"}],"melee":"bite +20 (2d8+12), 2 claws +20 (2d6+8), 2 wings +15 (1d8+4), tail slap +15 (2d6+12)","space":"15 ft.","reach":"10 ft. (15 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"50 ft. cone, DC 17, 12d6 cold plus bull rush [Small or smaller]"},{"type":"crush"}],"spell_like_abilities_caster_level":14,"spell_like_abilities_concentration":19,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"create water"},{"spell":"obscuring mist"},{"spell":"stinking cloud"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":5,"spellsknown_concentration":10,"spellsknown":[{"spell_level":2,"spell_slots":5,"spells":[{"spell":"invisibility"},{"spell":"whispering wind"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"feather fall"},{"spell":"hypnotism"},{"spell":"shocking grasp"},{"spell":"unseen servant"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"daze"},{"spell":"mage hand"},{"spell":"message"},{"spell":"open/close"},{"spell":"ray of frost"}]}],"strength":27,"dexterity":12,"constitution":21,"intelligence":16,"wisdom":19,"charisma":18,"baseatk":14,"cmb":25,"cmd":34,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Flyby Attack"},{"feat":"Hover"},{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Skill Focus (Fly)"},{"feat":"Wingover"}],"skills":[{"skill":"Bluff","value":21},{"skill":"Diplomacy","value":21},{"skill":"Fly","value":16},{"skill":"Intimidate","value":21},{"skill":"Knowledge (arcana)","value":20},{"skill":"Knowledge (nature)","value":20},{"skill":"Perception","value":25},{"skill":"Sense Motive","value":25},{"skill":"Spellcraft","value":20}],"languages":["Auran","Aquan","Common","Draconic","Giant"],"sq":[{"type":"cloud form"}],"environments":["temperate mountains","warm mountains"],"organizations":["solitary","clan (2-5)"],"treasure":"triple standard","description_visual":"This dragon has a fringed and frilled head and wings that sweep back from its shoulders to its tail. Large, piercing rose colored eyes dominate its somewhat triangular head. Its tail trails off becoming misty and translucent near the tip.","group":"Dragon","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"A cloud dragon's breath weapon is a powerful cone of icy cold air. When a cloud dragon uses its breath weapon, make a single bull rush attack using the dragon's CMB against the CMD of any creature that failed its Reflex save and is three or more size categories smaller than the dragon. This bull rush doesn't provoke attacks of opportunity, and the dragon cannot choose to move with any opponent pushed back. In addition to being pushed back, affected creatures are knocked prone and take 1d4 points of nonlethal damage per 10 ft. they are pushed back. Flying creatures are buffeted and pushed back twice the distance and sustain 1d6 points of nonlethal damage per 10 ft. they are pushed back."},{"type":"Cold Bite","kind":"Su","details":"At old age, a cloud dragon's bite deals an additional 2d6 points of cold damage. An ancient dragon's damage increases to 4d6, and a great wrym's to 6d6."},{"type":"Cloud Form","kind":"Su","details":"As a standard action, a juvenile or older cloud dragon can assume gaseous form at will, but it can remain gaseous indefinitely and has a fly speed of 20 ft. with perfect maneuverability."},{"type":"Cloud Vision","kind":"Ex","details":"A very young cloud dragon can see perfectly in foggy conditions (such as those created by fog cloud or obscuring mist)."},{"type":"Immunity to Winds","kind":"Su","details":"A cloud dragon is immune to the effects of wind. It ignores the penalties applied to the Fly skill incurred by wind speed, and is immune to the negative effects of any spell or effect that manipulates wind, such as gust of wind and whirlwind. Spell-like Abilities A cloud dragon gains the following spelllike abilities, usable at will upon reaching the listed age category. Young-create water; Juvenile-obscuring mist; Adult-stinking cloud; Old-call lightning; Ancient-control winds; Great Wyrm-control weather."},{"type":"Whirlwind","kind":"Sp","details":"A great wyrm cloud dragon can use this ability three times per day. It works as a whirlwind spell. This ability is the equivalent of an 8th-level spell."}],"description":"Cloud dragons are the most reclusive of all dragons, rarely leaving the safety and sanctity of their cloudy lairs. They have a great dislike for non-flying creatures and creatures that must use non-natural means to fly (such as through magical items or spells). A cloud dragon wyrmling's scales are silvery-blue with a slight hint of red at the tip of each scale. As the dragon ages, its color slowly changes to a bright sunset orange. The oldest cloud dragons resemble gold dragons, save for the large bony plates on their heads and backs. Cloud dragons are not highly aggressive, but dislike interlopers and attack them on sight. They open combat using their breath weapon, followed by their spell-like abilities. A cloud dragon rarely lands, preferring to fight from the air.","ecology":"","habitat_society":"","credit":"The Cloud Dragon originally appeared in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Adult Mist Dragon","cr":11,"xp":12800,"alignment":"N","size":"Huge","type":"dragon","subtypes":["air","fire","water"],"init":4,"senses":[{"type":"dragon senses"},{"type":"mist vision"}],"auras":["frightful presence (180 ft., DC 23)"],"ac":28,"ac_touch":8,"ac_flat_footed":28,"ac_mods":"+20 natural, -2 size","hp":184,"hd":"16d12+80","hdvalue":16,"fort":17,"ref":10,"will":15,"dr":"5/magic","immunities":["fire","paralysis","sleep"],"sr":22,"weaknesses":["vulnerability to cold"],"speed":[{"type":"land","speed":40},{"type":"fly","speed":200,"maneuverability":"poor"},{"type":"swim","speed":20}],"melee":"bite +22 (2d8+12), 2 claws +22 (2d6+8), 2 wings +20 (1d8+4), tail slap +20 (2d6+12)","space":"15 ft.","reach":"10 ft. (15 ft. with bite)","special_attacks":[{"type":"boiling bite"},{"type":"breath weapon","details":"cone, Fort DC 23, 6d6 fire plus blindness"},{"type":"crush"}],"spell_like_abilities_caster_level":16,"spell_like_abilities_concentration":21,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"create water"},{"spell":"fog cloud"},{"spell":"wind wall"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":5,"spellsknown_concentration":10,"spellsknown":[{"spell_level":2,"spell_slots":5,"spells":[{"spell":"daze monster"},{"spell":"see invisibility"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"burning hands"},{"spell":"magic missile"},{"spell":"obscuring mist"},{"spell":"shield"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"detect magic"},{"spell":"flare"},{"spell":"ghost sound"},{"spell":"message"},{"spell":"touch of fatigue"}]}],"strength":27,"dexterity":10,"constitution":21,"intelligence":20,"wisdom":21,"charisma":20,"baseatk":16,"cmb":26,"cmd":36,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Combat Expertise"},{"feat":"Flyby Attack"},{"feat":"Great Fortitude"},{"feat":"Hover"},{"feat":"Improved Initiative"},{"feat":"Multiattack"},{"feat":"Wingover"}],"skills":[{"skill":"Bluff","value":24},{"skill":"Diplomacy","value":24},{"skill":"Fly","value":11},{"skill":"Knowledge (arcana)","value":24},{"skill":"Knowledge (history)","value":24},{"skill":"Knowledge (nature)","value":24},{"skill":"Perception","value":28},{"skill":"Sense Motive","value":28},{"skill":"Spellcraft","value":24},{"skill":"Swim","value":35},{"skill":"Use Magic Device","value":24}],"languages":["Auran","Aquan","Celestial","Common","Draconic","Ignan","Sylvan"],"sq":[{"type":"mist form"},{"type":"water breathing"}],"environments":["any aquatic","temperate forests","warm forests"],"organizations":["solitary","clan (2-5)"],"treasure":"triple standard","description_visual":"This great dragon has a ridge of swept-back horns encircling its head with two larger and longer horns just above its eyes dominating the others. A ridge of similar smaller horns runs the length of its back from its shoulders to its tail. Its body is long, snake-like, and semi-material. It possesses no visible wings. Its scaled body is grayish-white.","group":"Dragon","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Boiling Bite","kind":"Su","details":"At old age, a mist dragon's bite deals an additional 2d6 points of fire damage. An ancient dragon's damage increases to 4d6, and a great wrym's to 6d6."},{"type":"Breath Weapon","kind":"Su","details":"A mist dragon's breath weapon is a cone of cloudy scalding vapor. In still air, the vapor lingers for 1d4 rounds and forms a cloud that covers a radius equal to the cone's length; on the second round, the vapor condenses into a heated smothering fog that deals 1d6 points of fire damage to creatures each round they remain in the area (Fortitude save halves this damage). The fog also blinds creatures (as the blindness spell) that fail the save as long as they remain within in the cloud and for 2 rounds after they leave the area."},{"type":"Mist Form","kind":"Su","details":"As a standard action, a juvenile or older mist dragon can assume gaseous form, but it can remain gaseous indefinitely and has a fly speed of 20 ft. with perfect maneuverability. A great wyrm mist dragon's abilities while in mist form improve drastically. As a standard action a great wyrm mist dragon in mist form can make a single melee attack of its choice at its highest attack bonus. This attack deals normal damage. As a full-round action, a great wyrm mist dragon in mist form can attack with its breath weapon."},{"type":"Mist Vision","kind":"Ex","details":"A very young mist dragon can see perfectly in foggy conditions (such as those created by fog cloud or obscuring mist). Spell-like Abilities A mist dragon gains the following spelllike abilities, usable at will upon reaching the listed age category. Young-create water; Juvenile-fog cloud; Adult-wind wall; Old-solid fog; Ancient-control winds; Great Wyrm-control water."},{"type":"Water Breathing","kind":"Ex","details":"A very young or older mist dragon can breathe underwater indefinitely and can freely use its breath weapon, spells, and other abilities while submerged."}],"description":"Mist dragons are relatively passive (for dragons) and reclusive, preferring to spend their time away from most other races (including other mist dragons). Mist dragons make their lairs near large sources of water such as waterfalls, lakes, and seashores. A mist dragon resembles a gold dragon in shape and size. Its scales are shiny-blue white as a hatchling and gradually darken to a blue-gray color with metallic silver splotches. Mist dragons usually spend their days moving from place to place in mist form. If threatened or angered, a mist dragon assumes solid form and attacks using its breath weapon, claws, and bite.","ecology":"","habitat_society":"","credit":"The Mist Dragon originally appeared in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Aerial Servant","cr":11,"xp":12800,"alignment":"N","size":"Medium","type":"outsider","subtypes":["air","elemental","extraplanar"],"init":10,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":24,"ac_touch":16,"ac_flat_footed":18,"ac_mods":"+6 Dex, +8 natural","hp":138,"hd":"12d10+72","hdvalue":12,"fort":10,"ref":14,"will":10,"defensive_abilities":["natural invisibility"],"dr":"10/magic","immunities":["elemental traits"],"speed":[{"type":"land","speed":60},{"type":"fly","speed":60,"maneuverability":"perfect"}],"melee":"2 slams +19 (2d8+6 plus grab)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"constrict","details":"2d8+6"},{"type":"wind blast"}],"strength":23,"dexterity":22,"constitution":23,"intelligence":4,"wisdom":10,"charisma":11,"baseatk":12,"cmb":18,"cmb_special":"+4 vs. grapple","cmd":34,"feats":[{"feat":"Alertness"},{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Fly","value":20},{"skill":"Knowledge (planes)","value":5},{"skill":"Perception","value":19},{"skill":"Stealth","value":20},{"skill":"Survival","value":12}],"languages":["Auran","Common"],"sq":[{"type":"improved tracking"},{"type":"link with caster"}],"environments":["any (Plane of Air)"],"organizations":["solitary"],"treasure":"none","description_visual":"This creature appears as a man-sized humanoid composed of grayish white vapor. No facial features can be discerned.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Improved Tracking","kind":"Ex","details":"An aerial servant takes no penalty to Survival checks when tracking and moving at any speed."},{"type":"Link with Caster","kind":"Ex","details":"When summoned, an aerial servant creates a mental link between itself and the caster who summoned it. Should the aerial servant fail the mission it has been assigned, it returns to the caster and attacks him. The aerial servant can find the caster as long as they both are on the same plane of existence. If the caster leaves the plane, the link is temporarily broken. Once the caster returns or the aerial servant enters the plane the caster is on, the link is immediately reestablished and the aerial servant moves at full speed toward the caster's current location. Only when the aerial servant or caster is destroyed, is the link permanently broken."},{"type":"Natural Invisibility","kind":"Su","details":"This ability is constant, allowing an aerial servant to remain invisible even when attacking. This ability is inherent and isn't subject to the invisibility purge spell. Against foes that cannot pinpoint it, the aerial servant gains a +20 bonus on Stealth checks when moving, or +40 when standing still-these bonuses are not included in the statistics above. This ability doesn't function when an aerial servant is on the Astral Plane or Ethereal Plane, but instead grants the creature concealment (20% miss chance)."},{"type":"Wind Blast","kind":"Su","details":"Once every 1d4 rounds, as a standard action, an aerial servant can release a blast of wind in an 80-foot line. A creature struck takes 4d8 points of damage and those up to the aerial servant's size or smaller are knocked down and back 2d10 ft. An affected creature can attempt a DC 22 Reflex save to reduce the damage by half and avoid being knocked down. The save DC is Constitution-based."}],"description":"Aerial servants are semi-intelligent creatures from the Plane of Air that often roam the Astral and Ethereal planes. They normally are only found on the Material Plane as a result of being summoned by a cleric (or, less frequently, a wizard) using the greater planar ally or greater planar binding spell and commanded to perform some task, often being required to use their immense strength to carry objects or aid the summoner. Though an aerial servant performs whatever task is asked of it, it resents being summoned and forced to do another's bidding; therefore, it attempts to pervert the conditions of the summoning and its mission. An aerial servant that fails or is thwarted in its mission becomes insane and immediately returns to the caster who summoned it, either killing the caster or carrying the caster back to the Plane of Air with it.\n\nAerial servants are invisible on the Plane of Air. On other planes, they can be seen when they wish, though only vaguely, and appear as humanoids composed of whitish-gray vapor. Sometimes eyes, a nose, and a small mouth form in the vapor.\n\nAerial servants attack by using a shearing blast of wind as a weapon or by grabbing an opponent and crushing it within their powerful grasp.\n\nAerial servants can only be killed on their native plane. If slain elsewhere, they simply dissolve into wisps of vapor and return to their home plane.","ecology":"","habitat_society":""},{"name":"Aeshma Demon","cr":11,"xp":12800,"alignment":"CE","size":"Large","type":"outsider","subtypes":["chaotic","demon","evil","extraplanar"],"init":4,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"see invisibility"}],"ac":25,"ac_touch":13,"ac_flat_footed":21,"ac_mods":"+4 Dex, +12 natural, -1 size","hp":189,"hd":"14d10+112","hdvalue":14,"fort":12,"ref":13,"will":14,"dr":"10/good","immunities":["electricity","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10},{"type":"fire","value":10}],"sr":22,"speed":[{"type":"land","speed":40},{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"+1 wounding spear +21 (2d6+10/19-20/x3 plus 1 bleed) or 2 claws +19 (1d6+6)","ranged":"+1 wounding spear +19 (2d6+6/19-20/x3 plus 1 bleed)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"rage"}],"spell_like_abilities_caster_level":14,"spell_like_abilities_concentration":22,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"see invisibility"}]},{"frequency":"at-will","spells":[{"spell":"dispel magic"},{"spell":"greater teleport","details":"self plus 50 lbs. Of objects only"},{"spell":"unholy blight"}]},{"frequency":"1/day","spells":[{"spell":"summon","details":"level 5, 1 aeshma 35% or 4d10 dretches 35%"}]},{"frequency":"2/day","spells":[{"spell":"blasphemy"},{"spell":"web"}]}],"strength":23,"dexterity":18,"constitution":27,"intelligence":14,"wisdom":17,"charisma":17,"baseatk":14,"cmb":21,"cmd":35,"feats":[{"feat":"Blind-Fight"},{"feat":"Cleave"},{"feat":"Great Cleave"},{"feat":"Improved Critical (spear)"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Weapon Focus (spear)"}],"skills":[{"skill":"Diplomacy","value":20},{"skill":"Escape Artist","value":18},{"skill":"Fly","value":23},{"skill":"Knowledge (arcana)","value":19},{"skill":"Perception","value":28},{"skill":"Spellcraft","value":16},{"skill":"Stealth","value":17},{"skill":"Survival","value":20}],"languages":["Abyssal","Celestial","Draconic","telepathy 100 ft."],"environments":["any (Abyss)"],"organizations":["solitary","troupe (1 aeshma and 1-4 vrocks)"],"treasure":"standard","description_visual":"This creature appears to be an 8-foot tall humanoid with basalt-colored skin. Dark hair covers its head and its hair is long and braided. Its arms are well-muscled and its hands end in powerful claws. Its head is human-like and its eyes are sapphire blue. Large leathery, bat-like wings protrude from its shoulders.","group":"Demon","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Rage","kind":"Ex","details":"An aeshma that takes 50% or more of its total hit points in damage in combat flies into a berserk rage on its next turn, swinging madly with its spear. A raging aeshma fights until either it or its opponent is dead. An enraged aeshma gains +4 Strength and -2 AC. The aeshma can end its rage voluntarily."}],"description":"Aeshma are the demons of rage and anger. An aeshma is sometimes referred to as \"the fiend of the wounding spear.\" Aeshma are thoroughly malign and evil and care little for anything or anyone else. They are actively recruited into the Abyssal armies of the demon lords and princes for their skill and combat prowess. Often an aeshma is given the rank of commander or lieutenant and granted control over a retinue or battalion of lesser demons (usually vrocks or dretches).\n\nThe typical ashema stands 8 ft. tall and weighs about 500 pounds.\n\nMost aeshma disdain the use of armor, but occasionally don chainmail.\n\nAeshma are very potent fighters and prefer a straight fight to subterfuge.\n\nThey fight aggressively against any foe, relying on their claws only if they are unarmed.\n\nAn aeshma's natural weapons, as well as any weapons it wields, are treated as chaotic-aligned and evil-aligned for the purpose of overcoming damage reduction.","ecology":"","habitat_society":"","gear":"+1 wounding spear"},{"name":"Bronze Giant","cr":11,"xp":12800,"alignment":"N","size":"Huge","type":"humanoid","subtypes":["giant"],"init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":23,"ac_touch":9,"ac_flat_footed":22,"ac_mods":"+1 Dex, +14 natural, -2 size","hp":152,"hd":"16d8+80","hdvalue":16,"fort":15,"ref":8,"will":10,"defensive_abilities":["rock catching"],"dr":"10/-","resists":[{"type":"fire","value":20}],"speed":[{"type":"land","speed":40}],"melee":"longsword +21 (3d6+11) or 2 slams +21  (2d6+11)","ranged":"spear +11 (3d6+11) or rock +12 (2d6+16)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"rock throwing","details":"140 ft."},{"type":"sardonic laugh"}],"strength":33,"dexterity":13,"constitution":21,"intelligence":10,"wisdom":16,"charisma":14,"baseatk":12,"cmb":25,"cmd":36,"feats":[{"feat":"Alertness"},{"feat":"Awesome Blow"},{"feat":"Cleave"},{"feat":"Improved Bull Rush"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Martial Weapon Proficiency (longsword)"},{"feat":"Power Attack"}],"skills":[{"skill":"Climb","value":15},{"skill":"Craft (blacksmithing)","value":8},{"skill":"Intimidate","value":19},{"skill":"Perception","value":22}],"languages":["Common","Giant"],"environments":["temperate islands","temperate mountains"],"organizations":["solitary","family (2-4)"],"treasure":"standard","description_visual":"You see a huge muscular being that is often mistaken for a statue of the gods. I t is well proportioned and has flesh that gleams like polished bronze and hair the color of copper wire.","group":"Giant","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Sardonic Laugh","kind":"Su","details":"Once per round as a standard action, a bronze giant can unleash a bellowing laugh that strikes fear into the hearts of any creature within 100 ft. that hears it. Affected creatures that succeed on a DC 20 Will save are unaffected and immune to the sardonic laugh of that bronze giant for 24 hours. On a failed save, that creature is shaken for as long as it remains within 100 ft. of the bronze giant and for 2d4 rounds thereafter. The save DC is Charisma-based."}],"description":"These giants are said to by some to have been sired by the Vulcan gods.\n\nOthers claim that they are awakened constructs with the flesh and blood of a living being encased in a skin of pure bronze. Both could be true, for these giants truly do have hardened skin the color of bronze. Due to their unique skin, bronze giants disdain wearing any sort of crafted armor.\n\nBronze giants are loners, and tend to avoid large gatherings of their rare kind, seeking mates in volcanic regions, where they remain together long enough to ensure the survival of their progeny, teach them how to fight and then move on.\n\nAll bronze giants claim to be the descendants of mighty Talos and are known to hire themselves out as mercenaries and defenders of cities within eyesight of great volcanoes. More than one hero has sought out a bronze giant for training. They may also serve as heroes and brute force, their appearance on a battlefield often sending would be invaders fleeing.\n\nBronze giants stand about 25 ft. tall and weigh about 14,000 pounds.\n\nThey have hair of black, copper, red, or dark brown. Their eyes are gray, brown, or black. They speak Common and Giant. Bronze giants live to be 500 years old.\n\nBronze giants prefer to dress in loose-fitting garb, such as robes and tunics. Sandals, rather than boots are usually worn on their ft., and many bronze giants wear rings, bracelets, and other jewelry fashioned of silver, bronze, or gold.\n\nBronze giants start combat from a distance, hurling large rocks and using spears before closing to fight with fists or sword. When confronted by many foes they let out a self-deprecating laugh that strikes fear into their enemies.","ecology":"","habitat_society":"","gear":"longsword"},{"name":"Bronze Minotaur","cr":11,"xp":12800,"alignment":"N","size":"Large","type":"construct","init":-1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":26,"ac_touch":8,"ac_flat_footed":26,"ac_mods":"-1 Dex, +18 natural, -1 size","hp":107,"hd":"14d10+30","hdvalue":14,"fort":4,"ref":3,"will":4,"dr":"5/adamantine","immunities":["construct traits (+30 hp)","magic"],"speed":[{"type":"land","speed":20}],"melee":"large greataxe +23 (3d6+13/x3)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"breathe fire","details":"4d6, DC 17"}],"strength":28,"dexterity":9,"wisdom":11,"charisma":1,"baseatk":14,"cmb":24,"cmd":33,"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"This massive bronze figure is shaped as a common minotaur, although its sheer bulk and slow movements bely it is an automaton of some kind.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Immunity to Magic","kind":"Ex","details":"A bronze minotaur is immune to any spell or spell-like ability that allows spell resistance. In addition, certain spells and effects function differently against the creature, as noted: A magical attack that deals electricity damage slows a bronze minotaur (as the slow spell) for three rounds with no saving throw. A magical attack that deals fire damage breaks any slow effect on the bronze minotaur and heals one point of damage for every three points of damage the attack would otherwise deal. If the amount of healing would cause the bronze minotaur to exceed its full normal hit points, it gains any excess as temporary hit points. A bronze minotaur gets no saving throw against fire attacks."},{"type":"Breath Fire","kind":"Su","details":"A bronze minotaur can breathe fire as a free action on the first round of combat and every other round thereafter. A bronze minotaur's fiery breath shoots from its mouth in a 30 foot cone inflicting 4d6 damage. A DC 17 Reflex save can reduce the damage by half. The save DC is Constitution based."}],"description":"Tall, dark and powerfully built, the bronze minotaur is an intimidating sight. Standing over 8 ft. tall, and weighing nearly 4,000 pounds, it is a massive and impressive guardian.\n\nBronze minotaurs can understand simple commands from their creators. They follow these orders unswervingly.\n\nConstruction\n\nA bronze minotaur is constructed from 5,000 pounds of bronze, forged with rare minerals and oils casting at least 10,000 gp.\n\nBRONZE MINOTAUR\n\nCL 16th; Price 120,000 gp\n\nCONSTRUCTION\n\nRequirements Craft Construct, burning hands, geas/ quest, limited wish, polymorph any object, creator must be caster level 16th; Skill Craft (blacksmithing) DC 18; Cost 60,000 gp.","ecology":"","habitat_society":"","credit":"Original author Mark R. Shipley  Originally appearing in The Black Monastery (© Frog God Games/ Mark R. Shipley, 2011)"},{"name":"Chaaor Demon","cr":11,"xp":12800,"alignment":"CE","size":"Large","type":"outsider","subtypes":["chaotic","demon","evil","extraplanar"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":24,"ac_touch":14,"ac_flat_footed":21,"ac_mods":"+3 Dex, +10 natural, -1 size, +2 profane","hp":126,"hd":"11d10+66","hdvalue":11,"fort":15,"ref":10,"will":5,"dr":"10/good","immunities":["electricity","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10},{"type":"fire","value":10}],"sr":22,"speed":[{"type":"land","speed":30}],"melee":"2 claws +18 (1d8+8 plus grab), bite +18 (2d6+8)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"rend","details":"2 claws, 1d8+8"},{"type":"roar","details":"3/day, 60-ft. radius, Ref DC 21 half, 3d6 sonic damage"}],"spell_like_abilities_caster_level":11,"spell_like_abilities_concentration":17,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"darkness"},{"spell":"greater teleport","details":"self plus 50 pounds of objects only"},{"spell":"see invisibility"}]},{"frequency":"1/day","spells":[{"spell":"chaos hammer"},{"spell":"summon","details":"level 9, 2d4 dretches or 1 chaaor 35%"}]}],"strength":26,"dexterity":17,"constitution":22,"intelligence":8,"wisdom":14,"charisma":14,"baseatk":11,"cmb":20,"cmb_special":"+4 vs. grapple","cmd":35,"feats":[{"feat":"Awesome Blow"},{"feat":"Blind-Fight"},{"feat":"Cleave"},{"feat":"Great Cleave"},{"feat":"Great Fortitude"},{"feat":"Power Attack"}],"skills":[{"skill":"Climb","value":22},{"skill":"Intimidate","value":16},{"skill":"Perception","value":24},{"skill":"Sense Motive","value":16},{"skill":"Stealth","value":13}],"languages":["Abyssal","Common","telepathy 100 ft."],"environments":["any (Abyss)"],"organizations":["solitary","gang (2-5)","pack (6-11)"],"treasure":"standard","description_visual":"This creature appears as a huge hulking ape-like creature with a bear's head. Two large, downward-curving horns jut from its head. The beast's fur is reddish-black and matted with blood and its hands end in razorsharp claws.","group":"Demon","source":"Tome of Horrors Complete (3pp)","description":"One. Their savagery in battle has turned the stomach of even the stoutest demonic general.\n\nChaaor are used as shock troops in the Abyssal armies. Many are the demon lords that have sent a battalion of these fiends against an army, watching in delight as the brutal chaaor tore its way through the enemy's ranks. When not engaging in wars with other infernal creatures, the chaaor spends its time roaming the Abyss in hunting packs. They have no preference as to the type or strength of prey: they pretty much hunt and kill what they choose. Chaaor packs have been known to attack creatures much larger than themselves and kill all opponents in short order.\n\nA chaaor is a 12-foot tall, hulking, ape-like brute with the head of a bear.\n\nLarge downward curving, grayish-silver horns grow from its head and end in rounded points. The chaaor's body is covered in reddish-black fur and is almost always caked or matted in blood. The powerful arms of a chaaor end in razor-sharp and filthy claws-black in color. Long rows of sharpened teeth fill the chaaor's mouth. When moving, the chaaor usually drops to all fours. When facing an aggressor it assumes a bipedal stance.\n\nChaaor are deadly adversaries that relish the blood and adrenaline of battle. Their tactics are simple: target a foe, charge forward, and rake or slash with claws and bite. Often, a chaaor unleashes its mighty roar to begin a fight hoping to knock down as many foes as possible.\n\nA downed foe is leapt on by multiple chaaors who proceed to tear the opponent to pieces. Likewise, if a chaaor grabs a foe, it holds on while the others move in and rip it to shreds with teeth and claws.","ecology":"","habitat_society":""},{"name":"Char Shambler","cr":11,"xp":12800,"alignment":"CE","size":"Medium","type":"magical beast","subtypes":["fire"],"init":4,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"auras":["desecrating aura (20 ft.)","smoke cloud (10 ft., DC 24)","stench (10 ft., DC 22, 1d8 rounds)"],"ac":25,"ac_touch":10,"ac_flat_footed":25,"ac_mods":"+15 natural","hp":147,"hd":"14d10+70","hdvalue":14,"fort":14,"ref":9,"will":6,"immunities":["fire"],"weaknesses":["vulnerability to cold"],"speed":[{"type":"land","speed":20}],"melee":"bite +19 (1d6+4 plus 1d6 fire), 2 claws +18 (1d4+4 plus 1d6 fire plus grab)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"burning touch"}],"strength":18,"dexterity":10,"constitution":20,"intelligence":7,"wisdom":10,"charisma":12,"baseatk":14,"cmb":18,"cmb_special":"+4 vs. grapple","cmd":28,"feats":[{"feat":"Ability Focus (smoke cloud)"},{"feat":"Cleave"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Skill Focus (Stealth)"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Intimidate","value":6},{"skill":"Perception","value":7},{"skill":"Stealth","value":11}],"languages":["Undercommon (cannot speak)"],"environments":["any land","any underground near cities"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"The humanoid creature looks like a mass of charred skin, burned black and hard with cracks showing raw, red flesh beneath. Visible waves of heat rise from this creature and a miasma of foul smoke seems to follow its every shuffling step, and the stench of scorched flesh and acrid smoke clings to its flesh.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Burning Touch","kind":"Su","details":"A char shambler that wins a grapple check establishes a hold, latching onto the opponent's body and automatically doing bite damage each round that the hold is maintained. In addition the fire damage from the bite attack increases from 1d6 on the first round to 3d6 points of damage on the third round. As the char shambler makes this attack it slowly begins charring its opponent. If it kills an opponent in this manner, the victim's flesh and tissues are completely charred away while the char shambler inhales the resulting smoke for its sustenance. It then devours the scorched and crumbling bones in 1d4 rounds."},{"type":"Desecrating Aura","kind":"Su","details":"Through the sheer foulness of its presence, a char shambler emits an aura within a 20- foot radius similar in effect to the secondary function of a desecrate spell (i.e. cutting off an area's connection to a non-associated deity and countering consecrate). This effect doesn't offer any bonuses to undead within the radius. Furthermore, it counters and dispels spells with the good descriptor within its area as if it was casting dispel magic as a 5th-level wizard."},{"type":"Smoke Cloud","kind":"Ex","details":"In addition to its stench, a char shambler continually gives off a cloud of acrid smoke from its scorched flesh. This cloud likewise affects all within 10 ft. of the char shambler. The smoke provides concealment (20% miss chance) to those within the cloud and they must make a Fortitude save each round (DC 24, +1 per previous check) or spend that round coughing and choking. This is saving throw in addition to the sickening effects of the char shambler's stench. A character who chokes for 2 consecutive rounds takes 1d6 points of nonlethal damage. The save DC is Constitution-based and includes a +2 bonus from its Ability Focus feat. A char shambler is immune to the effects of smoke (its own or otherwise) and ignores the concealment it provides as well."}],"description":"A char shambler is the result of a failed experiment to create a creature known as a charfiend from some base stock. The only documented examples come from the work of the lich Saca-Baroo and his experiments with the silid race, but other examples may exist.\n\nAs described, a char shambler's skin is charred and broken, and the creature lives in constant searing pain from the failed process that created it. It typically stands 6 to 7 ft. tall and weighs 300 pounds. Its face is a mask of charred flesh hiding the appearance of the original creature. This tough, charred shell provides it with good natural armor.\n\nWhether a char shambler can speak or not is unknown, as none have ever been known to. They do respond to commands in Common when under magical compulsion or a similar condition.\n\nA char shambler's existence is typically occupied by its never-ending desire to feed, and its actions tend to follow this course. When prey is spotted, it tries to disperse its enemies with its stench and smoke cloud so that it can focus on capturing and feeding on one individual without distractions.","ecology":"","habitat_society":"","credit":"Original author Greg A. Vaughan  Originally appearing in Slumbering Tsar (© Frog God Games/ Greg A. Vaughan, 2012)"},{"name":"Cinder Knight","cr":11,"xp":12800,"alignment":"N","size":"Medium","type":"outsider","subtypes":["elemental","extraplanar","fire"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["heat (10 ft., 1d6 fire)"],"ac":26,"ac_touch":11,"ac_flat_footed":25,"ac_mods":"+9 armor, +1 Dex, +6 natural","hp":142,"hd":"15d10+60","hdvalue":15,"fort":15,"ref":8,"will":12,"immunities":["elemental traits","fire"],"sr":21,"weaknesses":["vulnerability to cold"],"speed":[{"type":"land","speed":30,"special":"40 ft. without armor"}],"melee":"mwk greatsword +24 (2d6+10 plus 1d6 fire) or 2 slams +22 (1d4+7 plus 1d6 fire)","space":"5 ft.","reach":"5 ft.","strength":24,"dexterity":16,"constitution":18,"intelligence":11,"wisdom":12,"charisma":11,"baseatk":15,"cmb":22,"cmd":35,"feats":[{"feat":"Cleave"},{"feat":"Critical Focus"},{"feat":"Great Cleave"},{"feat":"Great Fortitude"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (greatsword)"}],"skills":[{"skill":"Diplomacy","value":18},{"skill":"Intimidate","value":18},{"skill":"Knowledge (planes)","value":18},{"skill":"Perception","value":19},{"skill":"Sense Motive","value":19},{"skill":"Survival","value":19}],"languages":["Common","Ignan"],"environments":["any (Plane of Fire)"],"organizations":["solitary"],"treasure":"standard (full plate armor, masterwork greatsword)","description_visual":"This intimidating figure stands unmoving, an immense sword clutched in its hands. Wisps of smoke rise from its blackened armor.","source":"Tome of Horrors 4 (3pp)","description":"Cinder knights are elemental creatures composed completely of fire and encased in suits of irremovable armor. Over time, the armor adheres to the cinder knight's form, and the armor chars and blackens as the flames of the cinder knight's body scorch and burns it. Cinder knights dwell on the Plane of Fire among other fire elementals and creatures. The creature's true origins are unknown, but some believe the cinder knight to be an advanced form of fire elemental or perhaps a fire elemental punished for some transgression.\n\nA cinder knight stands over 6 ft. tall and weighs 200 pounds (without its armor, its true form weighs less). The creature's true form is never seen, for when a cinder knight dies, its fires extinguish, and it vanishes in wisps of smoke, leaving only its armor behind. The armor is extremely hot to the touch and deals 1d6 points of fire damage to any creature touching it. One hour after a cinder knight dies, the armor, while still warm, can be handled without taking damage.\n\nA cinder knight rarely attacks using natural attacks, preferring the use of weapons in combat. Greatswords are the most common weapon, followed by mauls, longswords, and flails. Regardless of the weapon used, a cinder knight deals fire damage with its fire attack (a product of the creature itself and not the weapon).","ecology":"","habitat_society":""},{"name":"Corpsespinner","cr":11,"xp":12800,"alignment":"N","size":"Huge","type":"magical beast","subtypes":["extraplanar"],"init":7,"senses":[{"type":"astralsense"},{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":25,"ac_touch":11,"ac_flat_footed":22,"ac_mods":"+3 Dex, +14 natural, -2 size","hp":127,"hd":"15d10+45","hdvalue":15,"fort":12,"ref":12,"will":7,"speed":[{"type":"land","speed":40},{"type":"climb","speed":20}],"melee":"bite +18 (2d8+7/19-20 plus poison)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"create corpsespun"},{"type":"web","details":"ranged touch +16, DC 28, 15 hp"}],"strength":20,"dexterity":17,"constitution":17,"intelligence":7,"wisdom":15,"charisma":10,"baseatk":15,"cmb":22,"cmd":35,"cmd_special":"+12 vs. trip","feats":[{"feat":"Ability Focus (poison)"},{"feat":"Alertness"},{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Natural Attack (bite)"},{"feat":"Power Attack"},{"feat":"Skill Focus (Stealth)"}],"skills":[{"skill":"Climb","value":17},{"skill":"Perception","value":10},{"skill":"Sense Motive","value":8},{"skill":"Stealth","value":8}],"languages":["Aklo"],"sq":[{"type":"astral jaunt"}],"environments":["any (Astral Plane)"],"organizations":["solitary","troupe (1 plus 4-9 corpsespun)"],"treasure":"none","description_visual":"A massive, bone-white tarantula is the only way to describe this monster. Bands of gray and silver ring its abdomen and legs, and its body is covered in short, bristly hairs of white and silver. A large skull-like marking appears on the creature's thorax. Its eight eyes are stark white.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Astral Jaunt","kind":"Su","details":"A corpsespinner can shift from the Astral Plane to the Material Plane as a free action, and shift back again as a move action (or as part of a move action). The ability is otherwise identical to ethereal jaunt (CL 15th) except it accesses the Astral Plane."},{"type":"Astralsense","kind":"Su","details":"A corpsespinner can automatically detect the location of anything within 200 ft. of it on the Astral Plane."},{"type":"Create Corpsespun","kind":"Su","details":"Creatures slain by a corpsespinner but not devoured rise in 1 hour as a corpsespun creature."},{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 22; frequency 1/round for 4 rounds; effect 2d6 Intelligence damage, death at 0 Intelligence and rise as a corpsespun after 1 hour; cure 2 consecutive saves. The save DC is Constitution-based."},{"type":"Web","kind":"Ex","details":"As the standard ability but with range 80 ft. In addition the checks include both a +4 bonus because the webs are constructed of astral material and a +4 racial bonus. The corpsespinner cannot produce the magical astral webs during combat."}],"description":"Corpsespinners are highly aggressive extraplanar spiders originating on the Astral Plane. Only rarely do they enter the Material Plane in search of prey, choosing to hunt on the Astral Plane searching and devouring astral sharks and other native creatures. On the Material Plane, they often hunt other giant spiders or humanoids. On the Astral Plane, corpsespinners spend their time constructing elaborate webs. The webs use many different things as anchor points such as rare natural occurring materials on the Astral Plane, corpses of deceased astral travelers, and just about anything else the corpsespinner can incorporate into its webbing. When not constructing its webs, the corpsespinner is usually hunting. And this sometimes leads it to the Material Plane. If encountered on the Material Plane, there is a good chance the corpsespinner has a group of corpsespun with it, the victim's of its most recent kills. Corpsespinners are primarily solitary creatures in regards to associating with others of their kind. Their Ecology and reproduction cycles are unknown at this point, though intrepid interplanar adventurers have talked of huge webbed lairs on the Astral Plane containing young corpsespinners. Corpsespinners hunt their prey on the Astral Plane, only occasionally entering the Material Plane to look for food. Once prey is sighted, the corpsespinner moves quickly to encase it in its sticky webbing before attacking repeatedly with its poisonous bite. On the Material Plane it attacks a foe, shifts to the Astral Plane, and shifts back again to finish the opponent off. If forced to retreat, the corpsespinner shifts to the Astral Plane and returns to its lair. A corpsespinner usually has a gang of corpsespun with it (see the Corpsespun template in this book for details). In such a case, the corpsespinner attempts to web its foes and let the corpsespun move in to soften them up. The corpsespinner then charges in and bites its targets to finish them off.","ecology":"and reproduction cycles are unknown at this point, though intrepid interplanar adventurers have talked of huge webbed lairs on the Astral Plane containing young corpsespinners. Corpsespinners hunt their prey on the Astral Plane, only occasionally entering the Material Plane to look for food. Once prey is sighted, the corpsespinner moves quickly to encase it in its sticky webbing before attacking repeatedly with its poisonous bite. On the Material Plane it attacks a foe, shifts to the Astral Plane, and shifts back again to finish the opponent off. If forced to retreat, the corpsespinner shifts to the Astral Plane and returns to its lair. A corpsespinner usually has a gang of corpsespun with it (see the Corpsespun template in this book for details). In such a case, the corpsespinner attempts to web its foes and let the corpsespun move in to soften them up. The corpsespinner then charges in and bites its targets to finish them off.","habitat_society":""},{"name":"Crag Giant","cr":11,"xp":12800,"alignment":"CE","size":"Large","type":"humanoid","subtypes":["giant"],"init":0,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":25,"ac_touch":9,"ac_flat_footed":25,"ac_mods":"+16 natural, -1 size","hp":133,"hd":"14d8+70","hdvalue":14,"fort":14,"ref":4,"will":7,"defensive_abilities":["rock catching"],"speed":[{"type":"land","speed":40},{"type":"climb","speed":30}],"melee":"greatclub +18 (2d8+13) or 2 slams +18 (1d8+9)","ranged":"rock +10 (2d8+13)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"earth mastery"},{"type":"rock throwing","details":"180 ft."}],"spell_like_abilities_caster_level":14,"spell_like_abilities_concentration":19,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"earthquake"},{"spell":"summon monster VII","details":"earth elementals only"}]}],"strength":29,"dexterity":10,"constitution":21,"intelligence":10,"wisdom":12,"charisma":12,"baseatk":10,"cmb":20,"cmd":30,"feats":[{"feat":"Awesome Blow"},{"feat":"Cleave"},{"feat":"Improved Bull Rush"},{"feat":"Improved Sunder"},{"feat":"Intimidating Prowess"},{"feat":"Iron Will"},{"feat":"Martial Weapon Proficiency (greatclub)","type":"bonus"},{"feat":"Power Attack"}],"skills":[{"skill":"Climb","value":24},{"skill":"Intimidate","value":20},{"skill":"Perception","value":14},{"skill":"Stealth","value":2},{"skill":"Survival","value":5}],"languages":["Giant"],"sq":[{"type":"stonecunning"}],"environments":["any mountains"],"organizations":["solitary","gang (2-5)","band (4-8)","tribe (10-20 plus 40% noncombatants, 1-2 elders, and 4-8 gargoyles)"],"treasure":"standard (greatclub)","description_visual":"This muscular giant has dark brown skin and wild, long, black hair. It wields a huge club in its massive hands.","group":"Giant","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Earth Mastery","kind":"Ex","details":"A crag giant gains a +1 bonus on attack and damage rolls if both it and its foe are touching the ground. If an opponent is airborne or waterborne, the crag giant takes a -4 penalty on attack and damage rolls. These modifiers apply to bull rush and overrun maneuvers, whether the crag giant is initiating or resisting these kinds of attacks. (These modifiers are not included in the statistics block.)"},{"type":"Stonecunning","kind":"Ex","details":"This ability functions as the dwarf's stonecunning ability."}],"description":"Crag giants are malicious and capricious giants found inhabiting mountains and hills. They are highly territorial and attack most any creatures that wander into their lands. Bestial creatures are slaughtered and served as food while humanoids, especially dwarves, orcs, and humans are enslaved and forced into manual labor serving the crag giants and their ilk. When labor is in short supply and high demand, crag giant hunting parties venture forth, raiding nearby civilized lands and capturing whatever humanoids they can. Slave trade is common between crag giants, other giant races, and drow.\n\nCrag giants stand 11 ft. in height, and typical weigh around 1,100 pounds.\n\nSkin color is almost always dark brown, but some slate gray crag giants have been encountered. Hair on both males and females tends to be long and worn in ponytails. Hair color ranges from black to brown to red. Eyes are usually brown or green. Crag giants generally live to be 250 years old.\n\nCrag giants are violent creatures and wade headlong into combat, swinging their massive clubs or smashing their foes with their great fists. If interlopers are detected early and crag giants have the high ground, they bombard their foes with rocks, moving in to mop up any survivors.","ecology":"","habitat_society":""}];
